import { GraphQLClient, gql } from "graphql-request";

const client = new GraphQLClient("/graphql", {
  headers: { authorization: "Bearer " + token },
});

const GetUser = gql`
  query GetUser($id: ID!) {
    user(id: $id) {
      id
      name
      email
    }
  }
`;

interface GetUserData {
  user: { id: string; name: string; email: string };
}

const { user } = await client.request<GetUserData>(GetUser, { id: "1" });

const CreateUser = gql`
  mutation CreateUser($input: UserInput!) {
    createUser(input: $input) {
      id
      name
    }
  }
`;

try {
  const result = await client.request(CreateUser, {
    input: { name: "Ada", email: "ada@example.com" },
  });

  console.log(result.createUser.id);
} catch (error) {
  // error.response.errors holds GraphQL-level errors
  console.error(error.response?.errors);
}
